{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "rental_options_stack",
        "requirements_stack",
        "quick_actions_stack",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "LAX Standard SUV Rental Overview",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "For your rental needs at Los Angeles International Airport (LAX) from November 5th to November 12th, 2024, here are standard SUV options that typically include unlimited mileage and basic liability insurance. Prices and availability are subject to change and were retrieved on October 26, 2024, at 10:00 AM PST."
      },
      "children": []
    },
    "rental_options_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "rental_options_header_stack",
        "rental_options_intro_text",
        "rental_options_table"
      ]
    },
    "rental_options_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "car_icon",
        "rental_options_h2"
      ]
    },
    "car_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000838_01_1_car-front.svg"
      },
      "children": []
    },
    "rental_options_h2": {
      "type": "Text",
      "props": {
        "text": "Available Rental Options (Nov 5 - Nov 12)",
        "variant": "h2"
      },
      "children": []
    },
    "rental_options_intro_text": {
      "type": "Text",
      "props": {
        "text": "Below are illustrative options for a Standard SUV rental, including basic liability insurance and unlimited mileage, for pick-up at LAX on November 5, 2024, at 10:00 AM and return on November 12, 2024, at 10:00 AM."
      },
      "children": []
    },
    "rental_options_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "company",
            "label": "Company"
          },
          {
            "key": "vehicleType",
            "label": "Vehicle Type"
          },
          {
            "key": "totalPrice",
            "label": "Total Price (approx.)"
          },
          {
            "key": "mileage",
            "label": "Mileage"
          },
          {
            "key": "insurance",
            "label": "Insurance Included"
          }
        ],
        "rows": [
          {
            "company": "Hertz",
            "vehicleType": "Nissan Rogue/Ford Escape (or similar)",
            "totalPrice": "$785",
            "mileage": "Unlimited",
            "insurance": "Basic Liability"
          },
          {
            "company": "Avis",
            "vehicleType": "Ford Edge/Toyota RAV4 (or similar)",
            "totalPrice": "$810",
            "mileage": "Unlimited",
            "insurance": "Basic Liability"
          },
          {
            "company": "Enterprise",
            "vehicleType": "Hyundai Santa Fe/Chevy Equinox (or similar)",
            "totalPrice": "$799",
            "mileage": "Unlimited",
            "insurance": "Basic Liability"
          },
          {
            "company": "Budget",
            "vehicleType": "Kia Sorento/Jeep Cherokee (or similar)",
            "totalPrice": "$760",
            "mileage": "Unlimited",
            "insurance": "Basic Liability"
          },
          {
            "company": "National",
            "vehicleType": "Toyota RAV4/Nissan Rogue (or similar)",
            "totalPrice": "$830",
            "mileage": "Unlimited",
            "insurance": "Basic Liability"
          }
        ],
        "domain": "booking",
        "preferredPresentation": "cards",
        "primaryColumn": "company",
        "highlightColumns": [
          "totalPrice",
          "vehicleType"
        ],
        "numericColumns": [
          "totalPrice"
        ]
      },
      "children": []
    },
    "requirements_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "requirements_header_stack",
        "requirements_intro_text",
        "license_text",
        "credit_card_text",
        "proof_id_text",
        "insurance_text"
      ]
    },
    "requirements_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "card_list_icon",
        "requirements_h2"
      ]
    },
    "card_list_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000838_01_2_card-list.svg"
      },
      "children": []
    },
    "requirements_h2": {
      "type": "Text",
      "props": {
        "text": "US Car Rental Requirements for Drivers 30+",
        "variant": "h2"
      },
      "children": []
    },
    "requirements_intro_text": {
      "type": "Text",
      "props": {
        "text": "As a 30-year-old driver, you meet the standard age requirements for car rental in the US, which is typically 21 years old (though some companies may charge a young driver fee for those under 25). The general requirements you'll need are:"
      },
      "children": []
    },
    "license_text": {
      "type": "Text",
      "props": {
        "text": "Valid Driver's License: A current, valid driver's license issued from your country of residence. If you are a foreign national, an International Driving Permit (IDP) is often recommended alongside your national license, though not always legally required in all states. For US residents, a state-issued driver's license is sufficient."
      },
      "children": []
    },
    "credit_card_text": {
      "type": "Text",
      "props": {
        "text": "Credit Card: A major credit card in the renter's name for the security deposit and payment. Debit cards may be accepted but often come with stricter requirements, such as proof of a return flight or additional security checks."
      },
      "children": []
    },
    "proof_id_text": {
      "type": "Text",
      "props": {
        "text": "Proof of Identity: Sometimes, a secondary form of identification, such as a passport (especially for international travelers) or another government-issued ID, may be requested."
      },
      "children": []
    },
    "insurance_text": {
      "type": "Text",
      "props": {
        "text": "Minimum Liability Insurance: Rental companies typically include the minimum state-required liability insurance. However, this coverage is often very basic. You will usually be offered options to purchase additional coverage (e.g., Loss Damage Waiver, Supplemental Liability Insurance, Personal Accident Insurance) at the counter. Your personal auto insurance policy or credit card benefits might also offer coverage, so it's advisable to check those before arriving."
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_h2",
        "hertz_book_button",
        "avis_book_button",
        "enterprise_book_button",
        "insurance_info_button"
      ]
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "hertz_book_button": {
      "type": "Button",
      "props": {
        "label": "Book Hertz SUV"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.hertz.com/rentacar/reservation/"
          }
        }
      },
      "children": []
    },
    "avis_book_button": {
      "type": "Button",
      "props": {
        "label": "Book Avis SUV"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.avis.com/en/reservation"
          }
        }
      },
      "children": []
    },
    "enterprise_book_button": {
      "type": "Button",
      "props": {
        "label": "Book Enterprise SUV"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.enterprise.com/en/reserve.html"
          }
        }
      },
      "children": []
    },
    "insurance_info_button": {
      "type": "Button",
      "props": {
        "label": "Understand Rental Car Insurance"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nerdwallet.com/article/insurance/rental-car-insurance"
          }
        }
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_h2",
        "nerdwallet_source_button",
        "hertz_source_button",
        "avis_source_button",
        "enterprise_source_button"
      ]
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "nerdwallet_source_button": {
      "type": "Button",
      "props": {
        "label": "NerdWallet - Rental Car Insurance"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nerdwallet.com/article/insurance/rental-car-insurance"
          }
        }
      },
      "children": []
    },
    "hertz_source_button": {
      "type": "Button",
      "props": {
        "label": "Hertz Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.hertz.com"
          }
        }
      },
      "children": []
    },
    "avis_source_button": {
      "type": "Button",
      "props": {
        "label": "Avis Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.avis.com"
          }
        }
      },
      "children": []
    },
    "enterprise_source_button": {
      "type": "Button",
      "props": {
        "label": "Enterprise Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.enterprise.com"
          }
        }
      },
      "children": []
    }
  }
}
